WITH ranked AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY shipping_fee DESC NULLS LAST, id) AS rank_in_group FROM orders QUALIFY rank_in_group = 1) SELECT id, customer_id, store_id, order_date, status, channel, amount, discount, shipping_fee, CASE WHEN channel RLIKE '^(store|mobile)$' THEN 'EXTENDED' WHEN channel RLIKE '^(web|partner)$' THEN 'GROUP_A' ELSE 'CORE' END AS channel_zone FROM ranked;
